@@ -2073,44 +2100,7 @@ spoe_queue_context(struct spoe_context *ctx)
 		    (int)date.tv_sec, (int)date.tv_usec, agent->id, __FUNCTION__,
 		    ctx->strm);

-	/* Do not try to create a new applet if there is no server up for the
