-			SPOE_PRINTF(stderr, "%d.%06d [SPOE/%-15s] %s: stream=%p"
-				    " - cannot create SPOE appctx: max CPS reached\n",
-				    (int)date.tv_sec, (int)date.tv_usec, agent->id,
-				    __FUNCTION__, ctx->strm);
-			goto end;
-		}
-	}
-
-	appctx = spoe_create_appctx(conf);
