 	/* Finally try to wakeup an IDLE applet. */
 	if (!eb_is_empty(&agent->rt[tid].idle_applets)) {
 		struct eb32_node *node;

 		node = eb32_first(&agent->rt[tid].idle_applets);
 		spoe_appctx = eb32_entry(node, struct spoe_appctx, node);
 		if (node && spoe_appctx) {
